def format_whatsapp_payload(item: dict) -> dict:
    """
    تنسيق الرسالة النهائية في هيكل بيانات واتساب للإرسال.

    Formats the reply into a WhatsApp-compatible dispatch payload.
    Strips HTML tags and normalizes newlines for WhatsApp rendering.

    Args:
        item: Assembled response envelope.

    Returns:
        WhatsApp dispatch payload dict.
    """
    recipient = (
        item.get("phone_number")
        or item.get("channel_user_id")
        or item.get("customer", {}).get("phone_number", "+966501234567")
    )
    text = item.get("reply") or item.get("final_reply") or item.get("message", "")

    clean_text = re.sub(r"<[^>]*>", "", text)
    clean_text = re.sub(r"\n{3,}", "\n\n", clean_text)
    clean_text = clean_text.replace("**", "*").strip()

    return {
        "channel": "whatsapp",
        "recipient": recipient,
        "dispatched": True,
        "meta_payload": {
            "messaging_product": "whatsapp",
            "recipient_type": "individual",
            "to": re.sub(r"[^0-9]", "", recipient),
            "type": "text",
            "text": {"body": clean_text},
        },
        "message": clean_text,
        "timestamp": datetime.now(timezone.utc).isoformat(),
    }
   ========================================================================== */

/* === ACTIVE JAVASCRIPT IMPLEMENTATION === */
const item = $input.first()?.json || {};
const recipient = item.phone_number || item.channel_user_id || item.customer?.phone_number || '+966501234567';
const text = item.reply || item.final_reply || item.message || '';

// Clean for WhatsApp: remove HTML, excessive newlines, fix markdown
let cleanText = text
  .replace(/<[^>]*>/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/\*\*/g, '*')
  .trim();

return [{
  json: {
    channel: 'whatsapp',
    recipient: recipient,
    dispatched: true,
    meta_payload: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: recipient.replace(/[^0-9]/g, ''),
      type: 'text',
      text: { body: cleanText }
    },
    message: cleanText,
    timestamp: new Date().toISOString()
  }
}];

